/* Settings modal and settings-owned controls */

.settings-modal .settings-tab-panel {
  min-width: 0;
  padding-top: 0;
  overflow-x: clip;
}
.settings-modal .settings-row {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.settings-modal .settings-row .settings-section {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(180px, auto);
  gap: 16px;
  align-items: center;
  margin: 0;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}
.settings-modal .settings-row .settings-section > :only-child {
  grid-column: 1 / -1;
}
.settings-modal .settings-section {
  margin-top: 14px;
}
.settings-modal .settings-label {
  margin: 0;
  color: var(--text-primary);
  font-size: 14px;
}
.settings-modal .settings-group-title {
  margin-top: 22px;
  border: 0;
  padding-bottom: 0;
  font-family: var(--font-mono);
  letter-spacing: 0.1em;
}
.settings-modal .local-ai-settings {
  background: var(--bg-card);
  border-color: var(--border);
}
.settings-modal .settings-links-row {
  padding-top: 8px;
  border-top: 1px solid var(--border);
}
.settings-modal .settings-action-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}
.settings-modal .settings-action-row + .settings-action-row {
  margin-top: 14px;
}
.settings-modal .settings-copy {
  min-width: 0;
  flex: 1 1 auto;
}
.settings-modal .settings-copy-title {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
}
.settings-modal .settings-copy-desc {
  margin-top: 2px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.45;
}
.settings-modal .settings-divider {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px dashed var(--border);
}
.settings-modal .settings-token-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 6px;
}
.settings-modal .settings-token-actions {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}
.settings-modal .settings-token-box {
  min-height: 20px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-family: var(--font-mono, monospace);
  font-size: 11.5px;
  line-height: 1.6;
  word-break: break-all;
  user-select: none;
}
.settings-modal .settings-select {
  min-width: 90px;
  padding: 6px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--select-surface);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}
.settings-modal .settings-beta-badge {
  display: inline-block;
  margin-left: 5px;
  padding: 2px 5px;
  border: 1px solid var(--border);
  border-radius: 5px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: .06em;
}
.settings-modal .settings-mini-btn {
  padding: 3px 10px;
  font-size: 11px;
  white-space: nowrap;
}
.settings-modal .settings-full-btn {
  width: 100%;
  margin-top: 12px;
  padding: 7px 14px;
  font-size: 12px;
  white-space: nowrap;
}
.settings-modal .api-key-input {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  min-height: 40px;
}
.settings-modal .api-key-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-fill);
}
.settings-modal select.api-key-input {
  appearance: auto;
  -webkit-appearance: menulist;
  cursor: pointer;
  padding-right: 12px;
  background-color: var(--select-surface);
}
.settings-modal select.api-key-input option {
  background: var(--select-popup-surface);
  color: var(--text-primary);
}
@supports (appearance: base-select) {
  .settings-modal select.api-key-input,
  .settings-modal select.api-key-input::picker(select) {
    appearance: base-select;
  }
  .settings-modal select.api-key-input::picker(select) {
    max-height: min(360px, 60vh);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    background: var(--select-popup-surface);
    color: var(--text-primary);
    box-shadow: var(--shadow-lg);
  }
  .settings-modal select.api-key-input::picker-icon {
    color: var(--text-muted);
  }
  .settings-modal select.api-key-input option {
    padding: 8px 12px;
  }
}

/* API key and provider settings */
.api-key-input {
  width: 100%; padding: 10px 12px; border-radius: 6px;
  border: 1px solid var(--border); background: var(--bg-primary);
  color: var(--text-primary); font-size: 13px; font-family: monospace;
  margin-top: 8px; color-scheme: dark;
}
[data-theme="light"] .api-key-input { color-scheme: light; }
.api-key-input:focus { border-color: var(--accent); }
.api-key-status { font-size: 13px; margin-bottom: 4px; }
.api-key-notice {
  font-size: 11px; color: var(--text-muted); margin-top: 12px;
  padding: 10px; background: var(--bg-card); border-radius: var(--radius-sm);
  border: 1px solid var(--border); line-height: 1.5;
}
.ai-provider-panel { margin-top: 12px; }
.ai-provider-desc {
  font-size: 12px; color: var(--text-muted); line-height: 1.5; margin-bottom: 10px;
}
.ai-model-tip {
  font-size: 12px; line-height: 1.5; color: var(--text-secondary);
  border-left: 3px solid var(--accent); padding: 8px 12px; margin-bottom: 12px;
  background: var(--bg-hover); border-radius: 0 4px 4px 0;
}
/* Local AI settings in Settings modal */
.local-ai-settings { margin-top: 4px; }
.local-ai-status {
  display: flex; align-items: center; gap: 8px; font-size: 13px;
}
.local-ai-status-dot {
  width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted);
  flex-shrink: 0;
}
.local-ai-status-dot.connected { background: var(--green); box-shadow: 0 0 6px rgba(34,197,94,0.5); }
.local-ai-status-dot.disconnected { background: var(--red); }

/* Settings sections */
.settings-section { margin-top: 16px; }
.settings-label { font-size: 13px; font-weight: 600; display: block; margin-bottom: 8px; color: var(--text-secondary); }
.settings-group-title {
  font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--text-muted); margin-top: 24px; padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}

/* Settings tabs */

.settings-tab-panel { display: none; padding-top: 6px; }
.settings-tab-panel.active {
  display: block;
  animation: settingsTabFadeIn 0.2s ease;
}
@keyframes settingsTabFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}
.settings-tab-panel .settings-section:first-child { margin-top: 8px; }
.settings-tab-panel .settings-group-title:first-child { margin-top: 12px; }
.settings-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.settings-row .settings-section { margin-top: 8px; }
.settings-links-row { display: flex; flex-wrap: wrap; gap: 8px 16px; margin-top: 8px; }
.settings-link-btn {
  background: none; border: none; color: var(--text-muted); font-size: 13px;
  font-family: inherit; cursor: pointer; padding: 4px 0; text-decoration: none;
  transition: color 0.15s;
}
.settings-link-btn:hover { color: var(--text-primary); text-decoration: underline; }

/* Theme picker */
.settings-theme-toggle { display: flex; align-items: center; gap: 4px; }
.settings-theme-btn {
  padding: 4px 12px; border-radius: 6px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 12px;
  cursor: pointer; font-weight: 500; transition: all 0.15s; font-family: inherit;
}
.settings-theme-btn.active { background: var(--accent); color: white; border-color: var(--accent); }
.settings-theme-btn:hover:not(.active) { background: var(--bg-hover); }








@media (max-width: 720px) {

  .settings-modal .settings-row .settings-section {
    grid-template-columns: 1fr;
    gap: 8px;
    padding: 12px 0;
  }
  .settings-modal .settings-section {
    margin-top: 12px;
  }
  .settings-modal .settings-group-title {
    margin-top: 18px;
  }
  .settings-modal .settings-action-row {
    align-items: flex-start;
    gap: 12px;
  }
  .settings-modal .settings-action-row > .toggle-switch {
    margin-top: 2px;
  }
  .settings-modal .unit-toggle,
  .settings-modal .range-toggle {
    flex-wrap: wrap;
  }
  .settings-modal .range-toggle {
    width: 100%;
  }
  .settings-modal .range-toggle-btn {
    flex: 1 1 0;
    min-width: 0;
  }
  .import-reference-benchmark { align-items: stretch; flex-direction: column; }
  .import-reference-benchmark-actions { flex-basis: auto; width: 100%; }
  .import-reference-benchmark .import-btn { width: 100%; }
}

@media (max-width: 600px) {

}

@media (max-width: 500px) {

  .settings-row { grid-template-columns: 1fr; }
}

/* When chat is open, push the dashboard left by the chat panel's
   current user-selected width so content stays visible alongside the
   chat instead of hiding behind it. Fullscreen chat suppresses the shift since
   the panel covers everything. Mobile (<768px) is also no-op since
   chat is a 100%-width takeover. We deliberately don't transition the
   padding — Chromium aborts the transition partway through when the
   chat panel's own transform animation runs simultaneously. The snap
   is barely perceptible alongside the panel's slide-in. */
body.chat-open .main,
body.chat-autostart-reserved .main { padding-right: calc(32px + min(var(--chat-panel-current-width, 600px), 100vw)); }
body.chat-open.chat-fullscreen .main,
body.chat-autostart-reserved.chat-fullscreen .main { padding-right: 32px; }

body.chat-open:not(.chat-fullscreen) .dashboard-sticky-actions,
body.chat-autostart-reserved:not(.chat-fullscreen) .dashboard-sticky-actions {
  right: calc(32px + min(var(--chat-panel-current-width, 600px), 100vw));
}
@media (max-width: 768px) {
  body.chat-open:not(.chat-fullscreen) .dashboard-sticky-actions,
  body.chat-autostart-reserved:not(.chat-fullscreen) .dashboard-sticky-actions,
  body.chat-open:has(#chat-thread-rail.open):not(.chat-fullscreen) .dashboard-sticky-actions,
  body.chat-autostart-reserved:has(#chat-thread-rail.open):not(.chat-fullscreen) .dashboard-sticky-actions {
    right: 12px;
  }
}

.chat-backdrop.open { display: block; }
.chat-panel.open { transform: translateX(0); }
/* Fullscreen mode — chat takes the whole viewport. Toggle via the
   ⛶ button in the chat header. State persists in localStorage. */
.chat-panel.chat-panel-fullscreen { width: 100vw; }

.chat-panel-conversation {
  flex: 1; display: flex; flex-direction: column; min-width: 0;
}
/* Thread Rail */
.chat-thread-rail {
  width: 0; overflow: hidden; display: flex; flex-direction: column;
  border-right: 1px solid var(--border); background: var(--bg-primary);
  transition: width 0.25s ease; flex-shrink: 0;
}
.chat-thread-rail.open { width: var(--chat-rail-width, 220px); }
.chat-thread-rail-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 14px 10px; flex-shrink: 0;
}
.chat-thread-rail-title {
  font-family: var(--font-display); font-size: 13px; font-weight: 600;
  color: var(--text-primary); white-space: nowrap;
}
.chat-rail-back {
  display: none; background: none; border: none; color: var(--text-muted);
  font-size: 18px; cursor: pointer; padding: 0; line-height: 1; flex-shrink: 0;
  transition: color 0.15s;
}
.chat-rail-back:hover { color: var(--text-primary); }
@media (max-width: 768px) {
  .chat-thread-rail.open .chat-rail-back { display: block; }
}
.chat-thread-new-btn {
  width: 26px; height: 26px; border-radius: 6px; border: 1px solid var(--border);
  background: none; color: var(--text-muted); font-size: 16px; line-height: 1;
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  transition: all 0.15s; flex-shrink: 0;
}
.chat-thread-new-btn:hover { background: var(--bg-hover); color: var(--accent); border-color: var(--accent); }
.chat-thread-search {
  margin: 0 10px 8px; padding: 6px 10px; border-radius: 6px;
  border: 1px solid var(--border); background: var(--bg-secondary);
  color: var(--text-primary); font-size: 12px; font-family: inherit;
  flex-shrink: 0;
}
.chat-thread-search:focus { border-color: var(--accent); outline: none; }
.chat-thread-search::placeholder { color: var(--text-muted); }
.chat-thread-toolbar {
  display: flex; align-items: center; gap: 6px; margin: 0 10px 8px;
}
.chat-thread-sort-label {
  color: var(--text-muted); font-size: 10px; text-transform: uppercase; letter-spacing: .05em;
}
.chat-thread-sort {
  min-width: 0; flex: 1; height: 30px; padding: 4px 24px 4px 8px;
  border: 1px solid var(--border); border-radius: 6px; background: var(--bg-secondary);
  color: var(--text-secondary); font: inherit; font-size: 11px;
}
.chat-project-new-btn {
  width: 30px; height: 30px; flex: 0 0 30px; display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid var(--border); border-radius: 6px; background: transparent; color: var(--text-muted); cursor: pointer;
}
.chat-project-new-btn:hover { border-color: var(--accent); color: var(--accent); background: var(--bg-hover); }
.chat-project-new-btn svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.chat-thread-list {
  position: relative; flex: 1; overflow-y: auto; overscroll-behavior: contain; padding: 0 6px 10px;
}
.chat-thread-list:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.is-chat-thread-pointer-dragging,
.is-chat-thread-pointer-dragging * { cursor: grabbing !important; user-select: none !important; }
.chat-msg-highlight { box-shadow: inset 3px 0 0 var(--accent); }
.chat-search-mark { background: var(--accent); color: var(--bg-primary); border-radius: 2px; padding: 0 1px; }

/* Shared escaping Markdown renderer classes inside the authored summary dialog. */
.summary-modal-body a { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 2px; }
.summary-modal-body a:hover { text-decoration-thickness: 2px; }
.summary-modal-body .chat-h1 { font-size: 17px; font-weight: 700; margin: 14px 0 8px; font-family: var(--font-display); }
.summary-modal-body .chat-h1:first-child { margin-top: 0; }
.summary-modal-body .chat-h2 { font-size: 15px; font-weight: 600; margin: 12px 0 6px; font-family: var(--font-display); }
.summary-modal-body .chat-h2:first-child { margin-top: 0; }
.summary-modal-body .chat-h3 { font-size: 14px; font-weight: 600; margin: 10px 0 4px; color: var(--text-secondary); }
.summary-modal-body .chat-para { margin: 0 0 10px 0; }
.summary-modal-body .chat-para:last-child { margin-bottom: 0; }
.summary-modal-body .chat-list { margin: 0 0 10px 0; padding-left: 20px; }
.summary-modal-body .chat-list:last-child { margin-bottom: 0; }
.summary-modal-body .chat-list li { margin-bottom: 4px; }
.summary-modal-body .chat-list li::marker { color: var(--accent); }
.summary-modal-body .chat-code-block {
  background: var(--bg-primary); border: 1px solid var(--border); border-radius: 6px;
  padding: 12px 14px; margin: 8px 0; overflow-x: auto;
  font-family: 'SFMono-Regular', Consolas, monospace; font-size: 12px; line-height: 1.5; white-space: pre;
}
.summary-modal-body code { background: var(--bg-hover); padding: 1px 5px; border-radius: 3px; font-size: 12px; }
.summary-modal-body strong { font-weight: 600; }
.summary-modal-body .chat-table-wrap { overflow-x: auto; margin: 8px 0; border-radius: 6px; }
.summary-modal-body .chat-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.summary-modal-body .chat-table th, .summary-modal-body .chat-table td { padding: 6px 10px; border: 1px solid var(--border); text-align: left; }
.summary-modal-body .chat-table th { background: var(--bg-primary); font-weight: 600; font-size: 12px; }
.summary-modal-body .chat-blockquote { margin: 8px 0; padding: 8px 14px; border-left: 3px solid var(--accent); border-radius: 0 6px 6px 0; background: var(--bg-hover); color: var(--text-secondary); }
.summary-modal-body .chat-hr { border: none; border-top: 1px solid var(--border); margin: 12px 0; }
/* Local Knowledge Base — per-document row delete button */

/* Chat Example Prompts */
.chat-prompt-btn:where(:not([data-chat-provider-setup-view] *, [data-chat-empty-view] *)) {
  padding: 10px 16px; border-radius: 20px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 13px;
  cursor: pointer; font-family: inherit; transition: all 0.15s; text-align: left;
}
.chat-prompt-btn:where(:not([data-chat-provider-setup-view] *, [data-chat-empty-view] *)):hover { border-color: var(--accent); color: var(--accent); background: rgba(79,140,255,0.05); }

.chat-cost-footnote:not(:where([data-chat-transcript-message] *)) {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 6px;
  opacity: 0.6;
}
.chat-provider-attribution:not(:where([data-chat-transcript-message] *, [data-chat-summary-dialog] *)) {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 650;
  margin-top: 6px;
}

.chat-panel.chat-onboarding-active .chat-messages {
  padding-bottom: 24px;
}
.chat-scroll-control {
  position: relative; z-index: 6; height: 0; flex: 0 0 0;
  display: flex; justify-content: center; pointer-events: none;
}
.chat-panel.chat-onboarding-active .chat-scroll-control { display: none; }
.chat-jump-latest {
  pointer-events: auto; display: inline-flex; align-items: center; gap: 6px;
  min-height: 34px; padding: 6px 12px; border: 1px solid var(--border);
  border-radius: 999px; background: var(--bg-card); color: var(--text-secondary);
  box-shadow: var(--shadow-md); font: inherit; font-size: 12px; font-weight: 600;
  cursor: pointer; transform: translateY(-44px);
  transition: color 0.15s, border-color 0.15s, background 0.15s, transform 0.15s;
}
.chat-jump-latest[hidden] { display: none; }
.chat-jump-latest:hover {
  color: var(--text-primary); border-color: var(--accent); background: var(--bg-hover);
  transform: translateY(-46px);
}
.chat-jump-latest:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.chat-jump-latest svg {
  width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2;
  stroke-linecap: round; stroke-linejoin: round;
}
.chat-jump-latest.has-new-content::after {
  content: ''; width: 6px; height: 6px; border-radius: 50%; background: var(--accent);
}
.chat-msg-auto:not([data-chat-transcript-message]) {
  font-size: 12px !important; color: var(--text-muted) !important;
  font-style: italic; padding: 6px 12px !important;
  background: transparent !important; border: none !important;
  border-left: none !important; max-width: 100% !important;
  align-self: center !important;
}
.chat-stopped-note:not(:where([data-chat-transcript-message] *)) {
  font-size: 11px; color: var(--text-muted); font-style: italic; margin-top: 6px;
}
/* Browser range pseudo-elements are the owned picker's custom CSS exception. */
[data-chat-model-picker-view] .chat-model-effort-control input[type="range"]::-webkit-slider-runnable-track {
  height: 7px; border-radius: 999px;
  background: linear-gradient(to right, var(--accent) 0 var(--chat-effort-progress), var(--bg-hover) var(--chat-effort-progress) 100%);
}
[data-chat-model-picker-view] .chat-model-effort-control input[type="range"]::-moz-range-track { height: 7px; border-radius: 999px; background: var(--bg-hover); }
[data-chat-model-picker-view] .chat-model-effort-control input[type="range"]::-moz-range-progress { height: 7px; border-radius: 999px; background: var(--accent); }
[data-chat-model-picker-view] .chat-model-effort-control input[type="range"]::-webkit-slider-thumb {
  width: 18px; height: 18px; margin-top: -5.5px; appearance: none; -webkit-appearance: none;
  border: 2px solid var(--bg-card); border-radius: 50%; background: var(--text-primary); box-shadow: 0 1px 5px rgba(0,0,0,.35);
}
[data-chat-model-picker-view] .chat-model-effort-control input[type="range"]::-moz-range-thumb {
  width: 16px; height: 16px; border: 2px solid var(--bg-card); border-radius: 50%; background: var(--text-primary); box-shadow: 0 1px 5px rgba(0,0,0,.35);
}

.chat-messages {
  flex: 1; overflow-y: auto; overscroll-behavior: contain; padding: 20px 24px;
  display: flex; flex-direction: column; gap: 14px;
}
.chat-msg:not([data-chat-transcript-message], [data-chat-onboarding-message]) {
  max-width: 88%; padding: 12px 16px; border-radius: 12px;
  font-size: 14px; line-height: 1.7; word-wrap: break-word;
  white-space: normal;
}
.chat-avatar-anchor { position: relative; }
.chat-msg.chat-avatar-anchor.chat-ai,
.typing-indicator.chat-avatar-anchor { margin-left: 36px; }
.chat-msg.chat-avatar-anchor.chat-user { margin-right: 36px; }
.chat-avatar-anchor::before {
  content: attr(data-chat-avatar-text);
  position: absolute; bottom: 0; display: grid; place-items: center;
  width: 28px; height: 28px; box-sizing: border-box; border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--border) 82%, transparent);
  background-color: var(--bg-card); background-image: var(--chat-avatar-image, none);
  background-position: center; background-repeat: no-repeat;
  background-size: var(--chat-avatar-image-size, auto);
  color: var(--text-primary); font-size: 15px; line-height: 1;
  box-shadow: 0 2px 8px color-mix(in srgb, #000 12%, transparent);
}
.chat-msg.chat-ai.chat-avatar-anchor::before,
.typing-indicator.chat-avatar-anchor::before { left: -36px; }
.chat-msg.chat-user.chat-avatar-anchor::before { right: -36px; }
.chat-avatar-anchor.chat-avatar-branded::before { background-color: #fff; }
.chat-avatar-anchor[data-chat-avatar-role="user"]:not(.chat-avatar-photo)::before {
