}
.chat-msg code { background: var(--bg-hover); padding: 1px 5px; border-radius: 3px; font-size: 12px; }
.chat-msg strong { font-weight: 600; }
.chat-msg.chat-user:not([data-chat-transcript-message], [data-chat-onboarding-message]) {
