  font-size: 12px; line-height: 1.5; white-space: pre;
}
.chat-table-wrap { overflow-x: auto; margin: 8px 0; border-radius: 6px; }
.chat-table {
  width: 100%; border-collapse: collapse; font-size: 13px;
}
.chat-table th, .chat-table td {
  padding: 6px 10px; border: 1px solid var(--border); text-align: left;
}
.chat-table th {
  background: var(--bg-primary); font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: 0.3px;
}
.chat-table tr:nth-child(even) td { background: var(--bg-hover); }
.chat-callout {
  margin: 8px 0; padding: 10px 14px; border-radius: 8px;
  background: var(--bg-hover); border: 1px solid var(--border);
  font-size: 13px; line-height: 1.6;
}
.chat-blockquote {
  margin: 8px 0; padding: 8px 14px; border-left: 3px solid var(--accent); border-radius: 0 6px 6px 0;
  background: var(--bg-hover); color: var(--text-secondary);
}
.chat-blockquote .chat-para { margin-bottom: 6px; }
.chat-blockquote .chat-para:last-child { margin-bottom: 0; }
.chat-hr { border: none; border-top: 1px solid var(--border); margin: 12px 0; }
.chat-msg a { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 2px; }
.chat-msg a:hover { text-decoration-thickness: 2px; }
.chat-user a { color: #fff; text-decoration-color: rgba(255,255,255,0.6); }
.chat-msg em { font-style: italic; }
.chat-user .chat-para { margin-bottom: 4px; }
.chat-user .chat-list { margin-bottom: 4px; }
/* Owned pre-response status animation; geometry and motion preference use Tailwind. */
@keyframes typingBounce {
  0%, 80%, 100% { transform: translateY(0); }
  40% { transform: translateY(-6px); }
}

@media (max-width: 375px) {
  .chat-messages { padding: 14px 12px; }
}

@media (max-width: 768px) {
  .chat-thread-rail .chat-thread-search { min-height: 44px; box-sizing: border-box; font-size: 16px; }

}

/* ═══ Chat thread rail: back button on mobile overlay ═══ */
@media (max-width: 768px) {
  /*
   * Mobile keyboards resize and, on iOS, can also pan the visual viewport
   * without changing the layout viewport used by position: fixed. Keep both
   * the header and composer inside the actually visible portion.
   */
  .chat-panel.open {
    top: var(--chat-visual-viewport-top, 0px);
    bottom: var(--chat-visual-viewport-bottom, 0px);
  }
  .chat-panel-conversation {
    min-height: 0;
    overflow: hidden;
  }
  .chat-messages { min-height: 0; }
  .chat-thread-rail.open .chat-thread-rail-header { padding-top: 10px; }
}

@media (pointer: coarse) {
  .chat-thread-new-btn { width: 44px; height: 44px; }
  .chat-project-new-btn { min-width: 44px; min-height: 44px; }
  .chat-rail-back { min-width: 44px; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; }

  .chat-history-earlier { min-height: 44px; }
}

/* App-extension quiz HTML retains its established class contract. First-party quiz uses scoped Tailwind. */
.chat-quiz-options:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { display: flex; flex-direction: column; gap: 8px; margin: 12px 0 10px; }
.chat-quiz-option:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) {
  display: flex; align-items: center; gap: 10px;
  width: 100%; padding: 12px 14px;
  background: var(--bg-card); border: 1px solid var(--border); border-radius: 10px;
  color: var(--text-primary); text-align: left; cursor: pointer;
  transition: border-color 0.15s, background 0.15s, transform 0.05s;
  font: inherit;
}
.chat-quiz-option:hover:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { border-color: var(--accent); background: color-mix(in srgb, var(--purple) 6%, transparent); }
.chat-quiz-option:active:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { transform: translateY(1px); }
.chat-quiz-option:focus-visible:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { outline: 2px solid var(--accent); outline-offset: 2px; }
.chat-quiz-recommended:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { border-color: color-mix(in srgb, var(--purple) 50%, transparent); }
.chat-quiz-recommended:hover:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { border-color: var(--accent); }
.chat-quiz-icon:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { font-size: 22px; line-height: 1; flex: 0 0 28px; text-align: center; }
.chat-quiz-body:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { flex: 1; display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.chat-quiz-body strong:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { font-size: 13.5px; }
.chat-quiz-body span:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { font-size: 12px; color: var(--text-muted); line-height: 1.35; }
.chat-quiz-body em.chat-quiz-rec:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { font-style: normal; color: var(--accent); font-weight: 500; }
.chat-quiz-arrow:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { font-size: 16px; color: var(--text-muted); flex: 0 0 auto; }
.chat-quiz-option:hover .chat-quiz-arrow:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { color: var(--accent); }
.chat-quiz-back:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) {
  display: inline-flex; align-items: center; gap: 4px;
  background: transparent; border: none; color: var(--text-muted);
  font-size: 12px; cursor: pointer; padding: 0 0 8px;
}
.chat-quiz-back:hover:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { color: var(--accent); }
.chat-quiz-link:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) {
  background: transparent;
  border: 0;
  padding: 0;
  color: var(--text-muted);
  cursor: pointer;
  font: inherit;
}
.chat-quiz-link:hover:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { color: var(--accent); }
.chat-quiz-link:focus-visible:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 2px; }
.chat-quiz-skip:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { text-align: center; margin-top: 14px; }
.chat-quiz-skip-btn:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) {
  background: transparent; border: 1px solid var(--border); border-radius: 8px;
  color: var(--text-secondary); padding: 8px 14px; font-size: 12.5px;
  cursor: pointer; transition: border-color 0.15s, color 0.15s;
  font-family: inherit;
}
.chat-quiz-skip-btn:hover:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) { border-color: var(--accent); color: var(--accent); }
/* Remaining cycle/supplement HTML shares these inputs until those owners migrate. */
.chat-onboard-input:where(:not([data-chat-profile-setup-view] *)) {
  flex: 1; min-width: 0; background: var(--bg-input, var(--bg-sidebar)); border: 1px solid var(--border);
  border-radius: var(--radius); color: var(--text-primary); padding: 7px 10px; font-size: 13px;
  font-family: var(--font-body); transition: border-color 0.2s;
}
.chat-onboard-input:where(:not([data-chat-profile-setup-view] *)):focus { border-color: var(--accent); outline: none; }
select.chat-onboard-input:where(:not([data-chat-profile-setup-view] *)) { background: var(--bg-input, var(--bg-sidebar)); color: var(--text-primary); }
select.chat-onboard-input:where(:not([data-chat-profile-setup-view] *)) option { background: var(--select-popup-surface); color: var(--text-primary); }
.chat-onboard-actions:where(:not([data-chat-provider-setup-view] *, [data-chat-optional-setup-view] *, [data-chat-empty-view] *)) { display: flex; flex-direction: column; gap: 8px; margin-top: 12px; }
.chat-onboard-complete-label:where(:not([data-chat-provider-setup-view] *, [data-chat-optional-setup-view] *, [data-chat-empty-view] *)) {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  max-width: 100%;
  margin: 0 0 10px;
  padding: 3px 0 8px;
  border-bottom: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.chat-onboard-cta:where(:not([data-chat-provider-setup-view] *, [data-chat-optional-setup-view] *, [data-chat-empty-view] *)) {
  display: inline-flex; align-items: center; gap: 6px; padding: 10px 18px;
  border-radius: 10px; border: 1px solid var(--accent); background: transparent;
  color: var(--accent); font-size: 13px; font-weight: 600; cursor: pointer;
  transition: all 0.2s; text-align: left;
}
.chat-onboard-cta:where(:not([data-chat-provider-setup-view] *, [data-chat-optional-setup-view] *, [data-chat-empty-view] *)):hover { background: var(--accent); color: #fff; }
.chat-onboard-cycle-hint {
  font-size: 12px; color: var(--text-secondary); background: var(--bg-sidebar);
  border-radius: 8px; padding: 10px 12px; margin: 10px 0 0;
  border: 1px solid var(--border);
}
.chat-onboard-cycle-hint p { margin: 0 0 8px; line-height: 1.5; }
.chat-onboard-cycle-form { display: flex; flex-direction: column; gap: 8px; }
.chat-onboard-cycle-dates { display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }
.chat-onboard-day { width: 48px; text-align: center; -moz-appearance: textfield; }
.chat-onboard-day::-webkit-inner-spin-button,
.chat-onboard-day::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
.chat-onboard-cycle-form .chat-onboard-next:where(:not([data-chat-profile-setup-view] *)) { align-self: flex-end; }
.chat-onboard-supps {
  font-size: 12px; color: var(--text-secondary); background: var(--bg-sidebar);
  border-radius: 8px; padding: 10px 12px; margin: 10px 0 0;
  border: 1px solid var(--border);
}
.chat-onboard-supps p { margin: 0 0 8px; line-height: 1.5; }
.chat-onboard-supp-form {
  display: flex; gap: 6px; align-items: center; flex-wrap: wrap;
}
.chat-onboard-supp-form .chat-onboard-input:where(:not([data-chat-profile-setup-view] *)) { min-width: 80px; }
.chat-onboard-supp-add {
  width: 32px; height: 32px; border-radius: var(--radius); border: 1px solid var(--accent);
  background: transparent; color: var(--accent); font-size: 18px; cursor: pointer;
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
  transition: background 0.2s, color 0.2s;
}
.chat-onboard-supp-add:hover { background: var(--accent); color: #fff; }
.chat-onboard-supp-item {
  display: flex; align-items: center; justify-content: space-between;
  padding: 4px 0; border-bottom: 1px solid var(--border); font-size: 12px;
}
.chat-onboard-supp-item:last-child { border-bottom: none; }
.chat-onboard-supp-remove {
  background: none; border: none; color: var(--text-muted); cursor: pointer;
  font-size: 16px; padding: 0 4px; line-height: 1;
}
.chat-onboard-supp-remove:hover { color: var(--red); }

/* Cold-visible Chat launcher and closed panel shell. */

.chat-fab {
  position: fixed; bottom: 24px; right: 24px; z-index: 240;
  width: 56px; height: 56px; border-radius: 50%; border: none;
  background: var(--accent-gradient); color: white;
  cursor: pointer; box-shadow: var(--shadow-lg);
  display: flex; align-items: center; justify-content: center;
  transition: transform 0.2s, box-shadow 0.2s;
}
.chat-fab:hover { transform: scale(1.08); box-shadow: 0 4px 20px rgba(79, 140, 255, 0.4); }
.chat-fab:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.chat-fab svg { width: 26px; height: 26px; fill: none; stroke: white; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.chat-fab.hidden { display: none; }
@media (max-width: 480px) {
  .chat-fab { width: 48px; height: 48px; bottom: 16px; right: 16px; }
  .chat-fab svg { width: 22px; height: 22px; }
}
.chat-fab-badge {
  position: absolute; top: -2px; right: -2px;
  width: 14px; height: 14px; border-radius: 50%;
  background: var(--red); border: 2px solid var(--bg-card);
  pointer-events: none;
}
.chat-fab-nudge { animation: fabNudge 3s ease-in-out 2s 2; }
@keyframes fabNudge {
  0%, 100% { transform: scale(1); }
  15% { transform: scale(1.12); }
  30% { transform: scale(1); }
  45% { transform: scale(1.08); }
  60% { transform: scale(1); }
}

.chat-backdrop {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.4); z-index: 250; display: none;
  overflow: hidden;
  /* Visual dimming only — pointer-events disabled so the dashboard
     stays interactive while chat is open. Closing the chat is via
     X button, Escape, or the fullscreen-mode toggle. */
  pointer-events: none;
}
.chat-panel {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(var(--chat-panel-width, 600px), 100vw);
  background: var(--bg-secondary); border-left: 1px solid var(--border);
  z-index: 260; display: flex; flex-direction: row;
  transform: translateX(100%); transition: transform 0.3s ease, width 0.25s ease;
  box-shadow: -4px 0 24px rgba(0,0,0,0.4); will-change: transform;
}
.chat-rail-back { display: none; }

.chat-panel {
  width: min(var(--chat-panel-width, 600px), 100vw);
  background: var(--bg-secondary);
  box-shadow: -16px 0 44px rgba(0, 0, 0, 0.36);
}
body.chat-autostart-reserved .main {
  padding-right: calc(32px + min(var(--chat-panel-current-width, 600px), 100vw));
}
body.chat-autostart-reserved.chat-fullscreen .main {
  padding-right: 32px;
}
.chat-fab {
  color: var(--on-accent);
  box-shadow: 0 12px 28px -8px color-mix(in srgb, var(--accent) 55%, transparent);
}
.chat-fab:hover {
  transform: translateY(-2px);
  box-shadow: 0 16px 34px -10px color-mix(in srgb, var(--accent) 65%, transparent);
}
.chat-fab svg {
  stroke: currentColor;
}

.view-btn.active,
.sex-toggle-btn.active,
.unit-toggle-btn.active,
.time-toggle-btn.active,
.range-toggle-btn.active,
.range-btn.active,
.settings-theme-btn.active,
.emf-room-tab.active,
.cl-tag-chip.active,
.onboarding-sex-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
}

@media (min-width: 1400px) {
  .chat-panel { width: min(var(--chat-panel-width, 600px), 100vw); }
  body.chat-autostart-reserved .main { padding-right: calc(32px + min(var(--chat-panel-current-width, 600px), 100vw)); }
  body.chat-autostart-reserved.chat-fullscreen .main { padding-right: 32px; }
}
@media (max-width: 768px) {
  .chat-panel:not(.open) {
    display: none;
  }
  .chat-panel {
    left: 0;
    right: 0;
    /* Fill the viewport rather than the document scrollbar gutter. */
    width: 100vw;
    max-width: none;
    border-left: 0;
  }
  body.chat-autostart-reserved .main { padding-right: 0; }
  body.chat-autostart-reserved.chat-fullscreen .main { padding-right: 0; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
}

@media (max-width: 768px) {
  /* Mobile chat is full-screen takeover — no need to shift the
     dashboard since the user can't see it anyway. */
  body.chat-open .main,
  body.chat-autostart-reserved .main { padding-right: 20px; }
  .chat-thread-rail.open {
    position: absolute; top: 0; left: 0; bottom: 0; width: 100%;
    z-index: 5; border-right: none;
  }
}
@media (max-width: 480px) {
  .chat-onboard-supp-form { flex-direction: column; align-items: stretch; }
  .chat-onboard-supp-form .chat-onboard-input { flex: unset; width: 100%; }
  .chat-onboard-supp-form select.chat-onboard-input { width: 100%; }
  .chat-onboard-supp-add { width: 100%; }
  .chat-onboard-cycle-dates { flex-direction: column; }
}
